{
  "root": "root_stack",
  "state": {
    "flights": [
      {
        "id": "ana",
        "airline": "ANA (Direct)",
        "fare": "GBP 1,035",
        "departure": "19:00",
        "arrival": "17:55+1",
        "travelTime": "13h 55m",
        "stops": "Direct",
        "decision": "Strong direct option",
        "description": "Direct service with strong fare in May window",
        "logoUrl": "../assets/r_000264_01_logo_ana_official.svg",
        "bookingUrl": "https://flights.ana.co.jp/en-gb/flights-from-london-to-tokyo",
        "bookingLabel": "Book ANA"
      },
      {
        "id": "ba",
        "airline": "British Airways (Direct)",
        "fare": "EUR 1,059",
        "departure": "11:50",
        "arrival": "10:25+1",
        "travelTime": "13h 35m",
        "stops": "Direct",
        "decision": "Fastest direct in snapshot",
        "description": "Direct routing with shortest direct block time in this snapshot",
        "logoUrl": "../assets/r_000264_01_logo_ba_official.png",
        "bookingUrl": "https://www.skyscanner.net/flights/airline-flights-to-city/tyoa/british-airways-ba/cheap-flights-with-british-airways-ba-flights-to-tokyo",
        "bookingLabel": "Book BA"
      },
      {
        "id": "emirates",
        "airline": "Emirates (via DXB)",
        "fare": "EUR 673",
        "departure": "20:20",
        "arrival": "22:30+1",
        "travelTime": "17h 10m",
        "stops": "1 stop (DXB)",
        "decision": "Cheapest snapshot fare",
        "description": "Lowest fare snapshot, but one-stop routing",
        "logoUrl": "../assets/r_000264_01_logo_emirates_official.png",
        "bookingUrl": "https://www.skyscanner.net/flights/airline-flights-to-city/hnd/emirates-ek/cheap-flights-with-emirates-ek-flights-to-tokyo-haneda",
        "bookingLabel": "Book Emirates"
      }
    ]
  },
  "elements": {
    "root_stack": {
      "type": "List",
      "props": {
        "gap": "lg"
      },
      "children": [
        "title",
        "context_section",
        "requirements_section",
        "comparison_title",
        "comparison_table",
        "booking_cards_title",
        "booking_cards_container",
        "quick_actions_title",
        "quick_actions_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Flight Booking Recommendation: London to Tokyo (Live May 2026 Snapshot)",
        "variant": "h1"
      },
      "children": []
    },
    "context_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "context_title",
        "context_body"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Snapshot Context",
        "variant": "h2"
      },
      "children": []
    },
    "context_body": {
      "type": "Text",
      "props": {
        "text": "This is a live market snapshot collected on 2026-02-16 for travel on 31 May 2026. Fares are volatile and may change at booking time.",
        "variant": "body"
      },
      "children": []
    },
    "requirements_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "requirements_title",
        "req_date_stack",
        "req_route_stack",
        "req_passengers_stack",
        "req_cabin_stack"
      ]
    },
    "requirements_title": {
      "type": "Text",
      "props": {
        "text": "Travel Requirements",
        "variant": "h2"
      },
      "children": []
    },
    "req_date_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "req_date_label",
        "req_date_value"
      ]
    },
    "req_date_label": {
      "type": "Text",
      "props": {
        "text": "Travel Date:",
        "variant": "label"
      },
      "children": []
    },
    "req_date_value": {
      "type": "Text",
      "props": {
        "text": "31 May 2026"
      },
      "children": []
    },
    "req_route_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "req_route_label",
        "req_route_value"
      ]
    },
    "req_route_label": {
      "type": "Text",
      "props": {
        "text": "Route:",
        "variant": "label"
      },
      "children": []
    },
    "req_route_value": {
      "type": "Text",
      "props": {
        "text": "London (LHR) -> Tokyo (HND)"
      },
      "children": []
    },
    "req_passengers_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "req_passengers_label",
        "req_passengers_value"
      ]
    },
    "req_passengers_label": {
      "type": "Text",
      "props": {
        "text": "Passengers:",
        "variant": "label"
      },
      "children": []
    },
    "req_passengers_value": {
      "type": "Text",
      "props": {
        "text": "2 Adults"
      },
      "children": []
    },
    "req_cabin_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "req_cabin_label",
        "req_cabin_value"
      ]
    },
    "req_cabin_label": {
      "type": "Text",
      "props": {
        "text": "Cabin Preference:",
        "variant": "label"
      },
      "children": []
    },
    "req_cabin_value": {
      "type": "Text",
      "props": {
        "text": "Premium Economy (where available)"
      },
      "children": []
    },
    "comparison_title": {
      "type": "Text",
      "props": {
        "text": "Flight Comparison (Live Sources)",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "statePath": "/flights",
        "columns": [
          {
            "key": "airline",
            "label": "Airline"
          },
          {
            "key": "fare",
            "label": "Fare"
          },
          {
            "key": "departure",
            "label": "Departure (LHR)"
          },
          {
            "key": "arrival",
            "label": "Arrival (HND)"
          },
          {
            "key": "travelTime",
            "label": "Travel Time"
          },
          {
            "key": "stops",
            "label": "Stops"
          },
          {
            "key": "decision",
            "label": "Decision"
          }
        ],
        "domain": "flight",
        "preferredPresentation": "cards",
        "sourceFormat": "markdown"
      },
      "children": []
    },
    "booking_cards_title": {
      "type": "Text",
      "props": {
        "text": "Booking Cards",
        "variant": "h2"
      },
      "children": []
    },
    "booking_cards_container": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "flight_card"
      ]
    },
    "flight_card": {
      "type": "Card",
      "props": {
        "flex": 1
      },
      "children": [
        "card_content_stack"
      ],
      "repeat": {
        "statePath": "/flights",
        "key": "id"
      }
    },
    "card_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "card_header_stack",
        "card_description",
        "card_book_button"
      ]
    },
    "card_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "card_logo",
        "card_title_stack"
      ]
    },
    "card_logo": {
      "type": "Image",
      "props": {
        "url": {
          "$item": "logoUrl"
        },
        "height": 40,
        "width": 40,
        "fit": "contain"
      },
      "children": []
    },
    "card_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "card_airline_text",
        "card_fare_text"
      ]
    },
    "card_airline_text": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "airline"
        },
        "variant": "h3"
      },
      "children": []
    },
    "card_fare_text": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "fare"
        },
        "variant": "body"
      },
      "children": []
    },
    "card_description": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "description"
        },
        "variant": "caption"
      },
      "children": []
    },
    "card_book_button": {
      "type": "Button",
      "props": {
        "label": {
          "$item": "bookingLabel"
        },
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": {
              "$item": "bookingUrl"
            }
          }
        }
      }
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "google_flights_button",
        "skyscanner_button"
      ]
    },
    "google_flights_button": {
      "type": "Button",
      "props": {
        "label": "Compare on Google Flights",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/travel/flights"
          }
        }
      }
    },
    "skyscanner_button": {
      "type": "Button",
      "props": {
        "label": "Check Heathrow -> Haneda market fares",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.skyscanner.gg/routes/lhr/hnd/london-heathrow-to-tokyo-haneda.html"
          }
        }
      }
    }
  }
}
